<div class="stats"><div class="stat"><span>Current Shift</span><b><?=$open?e($open['shift_no']):'None'?></b><small><?=$open?'Opened '.e($open['opened_at']):'Open a shift'?></small></div><div class="stat"><span>Opening Cash</span><b><?=money($open['opening_cash']??0)?></b><small>Drawer start</small></div><div class="stat"><span>Expected Cash</span><b><?=money($expectedCash)?></b><small>Cash payments + movements</small></div><div class="stat"><span>Status</span><b><?=$open?'OPEN':'CLOSED'?></b><small>Cashier control</small></div></div><div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Open Shift</h2></div></div><div class="panel-body"><?php if(!$open):?><form method="post" action="/?r=shift-open"><?=csrf_field()?><div class="form-grid"><label><span>Shift No</span><input name="shift_no" value="S-<?=date('Ymd-His')?>"></label><label><span>Opening Cash</span><input name="opening_cash" type="number" step="0.01" value="0"></label></div><button class="btn primary" style="margin-top:9px">Open Shift</button></form><?php else:?><div class="flash ok">Shift <?=e($open['shift_no'])?> is open.</div><?php endif;?></div></section><section class="panel"><div class="panel-head"><div><h2>Close Shift</h2></div></div><div class="panel-body"><?php if($open):?><form method="post" action="/?r=shift-close"><?=csrf_field()?><input type="hidden" name="shift_id" value="<?=$open['id']?>"><div class="form-grid"><label><span>Expected Cash</span><input value="<?=$expectedCash?>" readonly></label><label><span>Actual Cash Count</span><input name="actual_cash" type="number" step="0.01" required></label><label class="full"><span>Closing Note</span><textarea name="close_note"></textarea></label></div><button class="btn primary" style="margin-top:9px">Close Shift</button></form><?php else:?><div class="flash ok">No open shift.</div><?php endif;?></div></section></div><section class="panel" style="margin-top:10px"><div class="panel-head"><div><h2>Shift History</h2></div></div><div class="panel-body"><div class="table-wrap"><table class="table"><thead><tr><th>Shift</th><th>Date</th><th>Cashier</th><th>Opening</th><th>Expected</th><th>Actual</th><th>Variance</th><th>Status</th></tr></thead><tbody><?php foreach($history as $s):?><tr><td><?=e($s['shift_no'])?></td><td><?=e($s['business_date'])?></td><td><?=e($s['cashier'])?></td><td><?=money($s['opening_cash'])?></td><td><?=money($s['expected_cash'])?></td><td><?=money($s['actual_cash'])?></td><td><?=money($s['variance_amount'])?></td><td><span class="tag <?=$s['status']==='OPEN'?'green':'blue'?>"><?=e($s['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div></section>